struct Node {
    int v;
    struct Node *next;
};
int exercise_a(void) {
    struct Node c = {0, NULL}, b = {0, &c}, a = {0, &b};
    if (scanf("%d%d%d", &a.v, &b.v, &c.v) != 3)
        return 1;
    int sum = 0;
    for (struct Node *p = &a; p; p = p->next)
        sum += p->v;
    printf("%d\n", sum);
    return 0;
}
#include <stdio.h>

struct part_b_Node {
    int v;
    struct part_b_Node *next;
};
int exercise_b(void) {
    struct part_b_Node c = {0, NULL}, b = {0, &c}, a = {0, &b};
    if (scanf("%d%d%d", &a.v, &b.v, &c.v) != 3)
        return 1;
    c.next = &a;
    a.next = &b;
    b.next = NULL;
