    for (size_t i = 1; i < n; ++i) if (a[i] > best) best = a[i];
    *out = best;
    return 1;
}

int main(void) {
    int scores[] = {70, 95, 82}, result = 0;
    if (max_score(scores, 3, &result)) printf("%d\n", result);
    printf("%d\n", scores[0]);
    return 0;
}

