enum Status { OK, ZERO_DIVISOR, OVERFLOW };
static enum Status divide(int a, int b, int *out) {
    if (b == 0) return ZERO_DIVISOR;
    if (INT_MIN < -INT_MAX && a == INT_MIN && b == -1) return OVERFLOW;
    *out = a / b;
    return OK;
}

int main(void) {
    int result = 99;
    printf("%d\n", divide(8, 0, &result));
    if (divide(8, 2, &result) == OK) printf("%d\n", result);
