}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

typedef struct { int *data; size_t size, cap; } Vec;
static int push(Vec *v, int value) {
    if (v->size == v->cap) {
        size_t cap = v->cap ? v->cap : 2;
        if (v->cap) { if (cap > SIZE_MAX / 2) return 0; cap *= 2; }
        if (cap > SIZE_MAX / sizeof *v->data) return 0;
        int *next = realloc(v->data, cap * sizeof *v->data);
        if (!next) return 0;
        v->data = next; v->cap = cap;
    }
    v->data[v->size++] = value;
    return 1;
}

int main(void) {
    Vec v = {0};
    for (int i = 1; i <= 3; ++i)
        if (!push(&v, i)) { free(v.data); return 1; }
    printf("%zu %zu\n", v.size, v.cap);
    for (size_t i = 0; i < v.size; ++i) printf("%d%s", v.data[i], i + 1 == v.size ? "\n" : " ");
    free(v.data);
    return 0;
}

