#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <errno.h>

static int parse_row(const char *line, char *name, size_t cap, int *score) {
    const char *comma = strchr(line, ',');
    if (!comma || comma == line) return 0;
    size_t len = (size_t)(comma - line);
    if (len >= cap) return 0;
    const char *digits = comma + 1;
    if (!*digits) return 0;
    for (const char *p = digits; *p; ++p) if (*p < '0' || *p > '9') return 0;
    errno = 0; char *end;
    long value = strtol(digits, &end, 10);
    if (errno == ERANGE || *end || value > 100) return 0;
    memcpy(name, line, len); name[len] = '\0';
    *score = (int)value;
    return 1;
}

int main(void) {
    char name[16] = ""; int score = 0;
    if (parse_row("Alice,90", name, sizeof name, &score)) printf("%s %d\n", name, score);
    printf("%d\n", parse_row("Bob,90x", name, sizeof name, &score));
    return 0;
}

